/// <summary>
/// The service class for updating sales order integration staus.
/// </summary>
public class METUpdateSalesOrderIntegrationStatusService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// Updates the sales order integration status.
    /// </summary>
    /// <param name="_contract">
    /// The <C>METUpdateSalesOrderIntegrationStatusCollectionContract</C> instance
    /// </param>
    /// <returns>reponse as a data contract <c>METUpdateSalesOrderIntegrationStatusResponseCollectionContract</c> </returns>
    public METUpdateSalesOrderIntegrationStatusResponseCollectionContract updateSOIntegrationStatus(METUpdateSalesOrderIntegrationStatusCollectionContract _contract)
    {
        SalesTable      salesTable;
        METSalesTable   metSalesTable;
        SalesId         salesId;
        CustAccount     custAccount;
        METUpdateSalesOrderIntegrationStatusContract  requestContract;
        List                                 responseList = new List(Types::Class);
        METUpdateSalesOrderIntegrationStatusResponseCollectionContract response = new METUpdateSalesOrderIntegrationStatusResponseCollectionContract();
        ListEnumerator      salesListEnumerator = _contract.parmSalesList().getEnumerator();

        #OCCRetryCount

        changecompany(_contract.parmDataAreaId())
        {
            while(salesListEnumerator.moveNext())
            {
                METUpdateSalesOrderIntegrationStatusResponseContract updateResponse = new METUpdateSalesOrderIntegrationStatusResponseContract();
                requestContract = salesListEnumerator.current();

                try
                {

                    salesId = requestContract.parmSalesId();
                    custAccount = requestContract.parmCustAccount();

            
                    select firstonly RecId from metSalesTable
                        join RecId from salesTable
                            where salesTable.SalesId == salesId
                               && salesTable.CustAccount == custAccount
                               && metSalesTable.SalesTable == salesTable.RecId;

                    if(metSalesTable.RecId)
                    {
                        ttsbegin;
                        metSalesTable.selectForUpdate(true);
                        metSalesTable.IntegrationStatus = METIntegrationStatus::Acknowledged;
                        metSalesTable.doUpdate();
                        ttscommit;

                        this.updateSalesLines(salesId);
                        updateResponse.parmSuccess(NoYes::Yes);
                        updateResponse.parmMessage("@MET:SalesOrderUpdateSuccessful");
                    }
                }
                catch(Exception::Deadlock)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        updateResponse.parmSuccess(NoYes::No);
                        updateResponse.parmMessage("@MET:SalesOrderUpdateFailedDatabaseDeadlock");
                        throw Exception::Error;
                    }
                    else
                    {
                        retry;
                    }
                }
                catch(Exception::UpdateConflict)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            throw Exception::UpdateConflictNotRecovered;
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        updateResponse.parmSuccess(NoYes::No);
                        updateResponse.parmMessage("@MET:SalesOrderUpdateFailedDatabaseConflict");
                        throw Exception::UpdateConflict;
                    }
                }
                catch(Exception::CLRError)
                {
                    System.Exception interopException = CLRInterop::getLastException();
                    updateResponse.parmSuccess(NoYes::No);
                    updateResponse.parmMessage(interopException.ToString());
                }
                catch(Exception::Error)
                {
                    updateResponse.parmSuccess(NoYes::No);
                    updateResponse.parmMessage("@MET:SalesOrderUpdateFailed");
                }

                responseList.addEnd(updateResponse);
            }
        }
        response.parmSalesOrderIntegrationStatusResponseList(responseList);
        return response;
    }

    /// <summary>
    /// Updates the integration status of specified sales lines
    /// </summary>
    /// <param name = "salesId">Sales Id</param>
    public void updateSalesLines(SalesId salesId)
    {
        METSalesLine    metSalesLine;
        SalesLine       salesLine;

        ttsbegin;
        while select RecId from salesLine
            where salesLine.SalesId == salesId
            join metSalesLine
                where metSalesLine.SalesLine == salesLine.RecId
        {
            metSalesLine.selectForUpdate(true);
            metSalesLine.IntegrationStatus = METIntegrationStatus::Acknowledged;
            metSalesLine.doUpdate();
        }
        ttscommit;
    }
